SELECT COUNT(*) AS boundary_pairs, SUM(m.generated_at < f.generated_at) AS one_min_first, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, m.generated_at, f.generated_at))/1000, 1) AS avg_5m_minus_1m_ms FROM trade_signal m JOIN trade_signal f ON f.symbol = m.symbol AND f.interval_code = '5m' AND f.candle_open_time = m.candle_open_time - INTERVAL 4 MINUTE WHERE m.interval_code = '1m' AND m.generated_at BETWEEN '2026-10-11 00:00:00' AND '2026-10-12 15:00:00'